const result = $input.first().json;
const signals = result.signals || [];
const buys = [];
const sells = [];
const holds = [];

for (const signal of signals) {
  const row = {
    ticker: signal.ticker,
    signal: signal.signal,
    confidence: Number(signal.confidence || 0),
    predicted_price: Number(signal.predicted_price || 0),
    predicted_date: signal.predicted_date,
    created_at: signal.created_at
  };

  if (row.signal === 'BUY') buys.push(row);
  else if (row.signal === 'SELL') sells.push(row);
  else holds.push(row);
}

buys.sort((a, b) => b.confidence - a.confidence);
sells.sort((a, b) => b.confidence - a.confidence);

return [{
  status: result.status || 'unknown',
  total: signals.length,
  buy_count: buys.length,
  sell_count: sells.length,
  hold_count: holds.length,
  top_buys: buys.slice(0, 5),
  top_sells: sells.slice(0, 5),
  timestamp: new Date().toISOString()
}];

const signalReport = $('Route Signals').first().json;
const tradeResult = $('Execute Paper Trades').first().json;
const portfolio = $input.first().json;
const summary = tradeResult.summary || {};
const ts = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });
const cash = Number(portfolio.cash || 0);
const starting = Number(portfolio.starting || 100000);
const pnl = cash - starting;
const pnlPct = starting ? (pnl / starting) * 100 : 0;

const lines = [];
lines.push('TradeIQ Auto-Trader Report');
lines.push(`${ts} IST`);
lines.push('');
lines.push(`Cash: INR ${cash.toLocaleString('en-IN', { maximumFractionDigits: 2 })}`);
lines.push(`Paper P&L: ${pnl >= 0 ? '+' : ''}${pnl.toFixed(2)} (${pnlPct.toFixed(2)}%)`);
lines.push(`Open positions: ${(portfolio.open_positions || []).length}`);
lines.push('');
lines.push(`Signals: BUY ${signalReport.buy_count}, SELL ${signalReport.sell_count}, HOLD ${signalReport.hold_count}`);
lines.push(`Trades this cycle: Buys ${summary.buys || 0}, Sells ${summary.sells || 0}, Skipped ${summary.skipped || 0}`);

if ((signalReport.top_buys || []).length) {
  lines.push('');
  lines.push('Top BUY signals:');
  for (const s of signalReport.top_buys) {
    lines.push(`${s.ticker}: confidence ${(s.confidence * 100).toFixed(0)}%, target ${s.predicted_price.toFixed(2)}`);
  }
}

if ((signalReport.top_sells || []).length) {
  lines.push('');
  lines.push('Top SELL signals:');
  for (const s of signalReport.top_sells) {
    lines.push(`${s.ticker}: confidence ${(s.confidence * 100).toFixed(0)}%, target ${s.predicted_price.toFixed(2)}`);
  }
}

return [{
  timestamp: new Date().toISOString(),
  message: lines.join('\n'),
  cash,
  starting,
  pnl,
  pnl_pct: pnlPct,
  open_positions: (portfolio.open_positions || []).length,
  recent_trades: portfolio.recent_trades || [],
  signal_report: signalReport,
  trade_summary: summary
}];
